import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, SkipForward, SkipBack, Volume2, X } from 'lucide-react';
import './Lecteur.css';

function Lecteur({ piste, playlist, onPisteChange, onFermer }) {
  const [enLecture, setEnLecture] = useState(false);
  const [progression, setProgression] = useState(0);
  const [duree, setDuree] = useState(0);
  const [volume, setVolume] = useState(1);
  const audioRef = useRef(null);

  useEffect(() => {
    if (piste) {
      if (audioRef.current) {
        audioRef.current.pause();
      }
      audioRef.current = new Audio(piste.url);
      audioRef.current.volume = volume;

      audioRef.current.addEventListener('loadedmetadata', () => {
        setDuree(audioRef.current.duration);
      });

      audioRef.current.addEventListener('timeupdate', () => {
        setProgression(audioRef.current.currentTime);
      });

      audioRef.current.addEventListener('ended', () => {
        passerSuivante();
      });

      audioRef.current.play();
      setEnLecture(true);
    }

    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
      }
    };
  }, [piste]);

  const passerSuivante = () => {
    if (!playlist || playlist.length === 0) return;
    const indexActuel = playlist.findIndex(p => p.url === piste.url);
    const indexSuivant = (indexActuel + 1) % playlist.length;
    onPisteChange(playlist[indexSuivant]);
  };

  const passerPrecedente = () => {
    if (!playlist || playlist.length === 0) return;
    const indexActuel = playlist.findIndex(p => p.url === piste.url);
    const indexPrecedent = (indexActuel - 1 + playlist.length) % playlist.length;
    onPisteChange(playlist[indexPrecedent]);
  };

  const toggleLecture = () => {
    if (enLecture) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setEnLecture(!enLecture);
  };

  const handleProgression = (e) => {
    const nouvellePosition = parseFloat(e.target.value);
    audioRef.current.currentTime = nouvellePosition;
    setProgression(nouvellePosition);
  };

  const handleVolume = (e) => {
    const nouvelleVolume = parseFloat(e.target.value);
    audioRef.current.volume = nouvelleVolume;
    setVolume(nouvelleVolume);
  };

  const formaterTemps = (secondes) => {
    if (!secondes || isNaN(secondes)) return '0:00';
    const min = Math.floor(secondes / 60);
    const sec = Math.floor(secondes % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
  };

  const pourcentage = duree > 0 ? (progression / duree) * 100 : 0;

  if (!piste) return null;

  return (
    <div className="lecteur-global">
      <div className="lecteur-gauche">
        {piste.pochette ? (
          <img src={piste.pochette} alt={piste.titre} className="lecteur-pochette" />
        ) : (
          <div className="lecteur-pochette-defaut">♪</div>
        )}
        <div className="lecteur-info">
          <span className="lecteur-titre">{piste.titre}</span>
          <span className="lecteur-artiste">{piste.artiste}</span>
        </div>
      </div>

      <div className="lecteur-centre">
        <div className="lecteur-controles">
          <button className="lecteur-btn" onClick={passerPrecedente}>
            <SkipBack size={20} />
          </button>
          <button className="lecteur-btn play" onClick={toggleLecture}>
            {enLecture ? <Pause size={24} /> : <Play size={24} />}
          </button>
          <button className="lecteur-btn" onClick={passerSuivante}>
            <SkipForward size={20} />
          </button>
        </div>
        <div className="lecteur-progression">
          <span className="lecteur-temps">{formaterTemps(progression)}</span>
          <div className="barre-progression-container">
            <div
              className="barre-progression-remplie"
              style={{ width: `${pourcentage}%` }}
            />
            <input
              type="range"
              min="0"
              max={duree || 0}
              value={progression}
              onChange={handleProgression}
              className="barre-progression-input"
            />
          </div>
          <span className="lecteur-temps">{formaterTemps(duree)}</span>
        </div>
      </div>

      <div className="lecteur-droite">
        <Volume2 size={16} color="#a0aec0" />
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={volume}
          onChange={handleVolume}
          className="volume-input"
        />
        <button className="lecteur-btn-fermer" onClick={() => {
          audioRef.current?.pause();
          onFermer();
        }}>
          <X size={18} />
        </button>
      </div>
    </div>
  );
}

export default Lecteur;
